/**
 * @summary Recent inbox messages from Gmail
 */
export const getListEmailMessagesUrl = (params?: ListEmailMessagesParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/email/messages?${stringifiedParams}`
    : `/api/email/messages`;
};

export const listEmailMessages = async (
  params?: ListEmailMessagesParams,
  options?: RequestInit,
): Promise<EmailSummary[]> => {
  return customFetch<EmailSummary[]>(getListEmailMessagesUrl(params), {
    ...options,
    method: "GET",
  });
};

